  (2, 'ZEST (ZRW-22015)', 'chartreuse-sun-zrw-22015', 'A zesty yellow textured co-ord made for days that need a little more colour. The oversized shirt, breezy wide-leg shorts and playful floral buttons keep it relaxed, fresh and ve...', 'Lawn / Jacquard', 9450, NULL, 'women', 4, 2, 'https://cdn.shopify.com/s/files/1/0081/0283/8329/files/01_0003_Gemini3_1Flash_NanoBanana2__0006_jpg.jpg?v=1788503110', 'https://cdn.shopify.com/s/files/1/0081/0283/8329/files/01_0001_Gemini3_1Flash_NanoBanana2__0010_jpg.jpg?v=1788503110', 'Multicolor, Pastel', 'S,M,L,XL', 4.6, 42, 0, 1, 20),
